{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C28"],
      "claim": "Safinamide absolute oral bioavailability was 95% (83.9–119.3%) after a 50 mg IR tablet in fasted subjects, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C53"],
      "claim": "Isoniazid absolute oral bioavailability was 93% in fasting adult patients with TB, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Isradipine absolute oral bioavailability was 16% in healthy subjects after oral versus IV administration, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Most transferred evidence molecules show absolute oral bioavailability values clearly above 20%, including safinamide, tolfenamic acid, nicotinic acid, bumetanide, bevantolol, KNI-272, tolterodine, Y-20811, and isoniazid. One molecule, isradipine, consistently shows healthy-subject bioavailability below 20%, creating a minority contradictory signal. The preponderance of direct absolute-bioavailability evidence supports high bioavailability.",
  "evidence_gaps": [
    "Minority contradictory evidence from isradipine (16% absolute F in healthy subjects) is not resolved by a clear assay-transfer difference, so some uncertainty remains.",
    "KNI-272 child data show 12% F, below threshold, while adult patient data are above 20%; population-specific transferability is uncertain."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

